// ════════════════════════════════════════════════════════════
// 环引擎 · 机制核心（酒馆助手脚本）
//
// 职责：全部公式的真算层。AI 不参与任何计算，只读取本引擎写回的变量。
// 架构：确定性优先（LCG 种子驱动，楼层重渲染结果不变）
// 依赖：MVU 变量框架（Mvu / getVariables / replaceVariables）
//
// 模块：
//   随机   LCG 确定性伪随机
//   判定   E3 标准判定链（D=P-R+E → S=clamp(50+D,5,95) → 档位联合判定）
//   时间   半天/楼层推进 + 历法（60 天/年 = 4 季 × 15 天）
//   求值   统一 Stat 求值器（声明式 STAT_DEF → resolveStat）
//   调度   事件调度器（冷却表 + 权重池 + 讲述者/难度修正）
//   财富   财富合计（袭击强度输入）
//
// 状态读写走 MVU：schema.ts 定义的 stat_data.* 路径
// ════════════════════════════════════════════════════════════

const 环引擎 = (function () {

  // ═══════════ 随机 · LCG ═══════════
  // state' = (1664525 × state + 1013904223) mod 2^32
  // 同一种子同一序号结果恒定，楼层重渲染不变

  function 下一随机(st) {
    st['$种子'] = (1664525 * st['$种子'] + 1013904223) % 4294967296;
    return st['$种子'] / 4294967296;
  }

  function 掷百分(st) { return 下一随机(st) * 100; }          // 0 ~ 99.99
  function 掷骰(st, 面) { return Math.floor(下一随机(st) * 面) + 1; }

  // ═══════════ 判定 · E3 ═══════════
  // cfg: { P: 能力值, R: 要求值, E: 环境修正, 修正: [] }
  // 返回: { 成功, 档位, 倍率, D, S, V }

  function 判定(st, cfg) {
    const D = cfg.P - cfg.R + (cfg.E || 0);
    const S = Math.max(5, Math.min(95, 50 + D));
    const V = 掷百分(st);
    const 成功 = V < S;
    let 档位 = '成功', 倍率 = 1.0;
    if (成功 && D >= 30) { 档位 = '大成功'; 倍率 = 1.5; }
    else if (成功 && D >= 10) { 档位 = '成功'; 倍率 = 1.0; }
    else if (成功) { 档位 = '勉强成功'; 倍率 = 0.6; }
    else if (D <= -30) { 档位 = '大失败'; 倍率 = 2.0; }       // 反噬
    else { 档位 = '失败'; 倍率 = 0; }
    return { 成功, 档位, 倍率, D, S: Math.round(S * 10) / 10, V: Math.round(V * 10) / 10 };
  }

  // ═══════════ 时间 · 推进器 ═══════════
  // 每楼层推进半天；60 天/年 = 4 季 × 15 天

  const 季表 = ['春', '夏', '秋', '冬'];

  function 推进半天(时间) {
    const t = _.cloneDeep(时间);
    if (t.时段 === '上午') { t.时段 = '下午'; }
    else {
      t.时段 = '上午';
      t.日 += 1;
      t.日计数 = (t.日计数 || 1) + 1;
      if (t.日 > 15) { t.日 = 1; t.季节 = 季表[(季表.indexOf(t.季节) + 1) % 4]; }
      if (t.季节 === '春' && t.日 === 1 && t.日计数 > 1) { t.年 += 1; }
    }
    return t;
  }

  function 日计数到阶段(n) {
    if (n <= 10) return '拓荒';
    if (n <= 30) return '发展';
    if (n <= 60) return '繁荣';
    return '终局';
  }

  // ═══════════ 求值 · 统一 Stat 求值器 ═══════════
  // STAT_DEF 声明式定义；resolveStat(殖民者, statId, context) 单一入口
  // 层序：基础值 → 技能偏移 → 容量修正 → 装备系数 → 环境修正 → 后处理钳制

  const STAT_DEF = {
    种植速度: { 基础: 1.0, 技能: { 名: '种植', 每级: 0.06 }, 容量: { 操作: 1.0 }, 环境: { 光照: 0.15, 温度: 0.2 } },
    建造速度: { 基础: 1.0, 技能: { 名: '建造', 每级: 0.08 }, 容量: { 操作: 1.0, 视觉: 0.4 }, 环境: { 光照: 0.15, 温度: 0.2 } },
    烹饪速度: { 基础: 1.0, 技能: { 名: '烹饪', 每级: 0.10 }, 容量: { 操作: 1.0 }, 环境: { 光照: 0.15 } },
    医疗质量: { 基础: 0.5, 技能: { 名: '医疗', 每级: 0.03 }, 容量: { 视觉: 1.0, 操作: 0.6 }, 环境: { 清洁: 0.2, 药品: 0.4 } },
    修复速度: { 基础: 1.0, 技能: { 名: '医疗', 每级: 0.05 }, 容量: { 操作: 1.0 }, 环境: { 药品: 0.3 } },
    研究速度: { 基础: 0.8, 技能: { 名: '智识', 每级: 0.05 }, 容量: { 视觉: 0.8, 意识: 0.5 }, 环境: { 光照: 0.15, 清洁: 0.1 } },
    载重: { 基础: 75, 容量: { 操作: 0.5, 意识: 0.3 }, 特质: true },
    产出效率: { 基础: 1.0, 技能: { 名: '种植', 每级: 0.03 }, 容量: { 操作: 1.0 } },
  };

  function resolveStat(殖民者, statId, context) {
    const def = STAT_DEF[statId];
    if (!def) return null;
    let v = def.基础;
    if (def.技能) {
      const sk = (殖民者.技能 || {})[def.技能.名] || { 等级: 0 };
      v += (sk.等级 || 0) * def.技能.每级;
    }
    if (def.容量 && context && context.容量) {
      for (const [容, 权] of Object.entries(def.容量)) {
        const cap = _.clamp(context.容量[容] ?? 1, 0, 2);
        v *= 1 - 权 * (1 - cap);
      }
    }
    if (def.环境 && context) {
      for (const [环, 权] of Object.entries(def.环境)) {
        const fac = _.clamp(context[环] ?? 1, 0.3, 1.5);
        v *= 1 - 权 * (1 - fac);
      }
    }
    return v;
  }

  // ═══════════ 调度 · 事件调度器 ═══════════
  // 事件 Def: { id, 类别, 条件(state), 权重, 冷却, 强度(state), 后果(state, rng, 强度) }
  // 每楼层：冷却递减 → 过滤条件 → 权重池 LCG 抽选 → 讲述者/难度修正 → 执行 → 写冷却

  const EVENTS = [];   // 事件注册点：模组包经此注册（Mod Pack Spec 注册点 4）

  function 注册事件(def) { EVENTS.push(def); }

  function 调度tick(st, ctx) {
    // 1 冷却递减
    for (const k of Object.keys(st.事件冷却 || {})) {
      st['$事件冷却'][k] = Math.max(0, st['$事件冷却'][k] - 1);
    }
    // 2 候选池
    const 候选 = [];
    for (const ev of EVENTS) {
      const cd = (st['$事件冷却'] || {})[ev.id] || 0;
      if (cd > 0) continue;
      if (ev.条件 && !ev.条件(st, ctx)) continue;
      候选.push(ev);
    }
    if (!候选.length) return null;
    // 3 权重修正（讲述者：卡桑德拉随时间增压/菲比温和/兰迪随机翻倍）
    const 讲 = st.世界.设置.讲述者;
    const 压 = 讲 === '兰迪' ? 下一随机(st) * 2 : (讲 === '菲比' ? 0.5 : Math.min(2, 0.8 + st.世界.日计数 / 60));
    // 4 加权抽选
    const 总权重 = 候选.reduce((s, e) => s + e.权重 * (e.类别 === '威胁' ? 压 : 1), 0);
    let roll = 下一随机(st) * 总权重;
    for (const ev of 候选) {
      roll -= ev.权重 * (ev.类别 === '威胁' ? 压 : 1);
      if (roll <= 0) {
        st['$事件冷却'][ev.id] = ev.冷却;
        const 强度 = ev.强度 ? ev.强度(st, ctx) : 0;
        return ev.后果(st, ctx, 强度);
      }
    }
    return null;
  }

  // ═══════════ 财富 · 合计 ═══════════

  function 财富合计(st) {
    st.财富.合计 = Math.round(
      (st.财富.物品 || 0) + (st.财富.建筑 || 0) +
      (st.财富.弹药 || 0) + (st.财富.殖民者与动物 || 0),
    );
    return st.财富.合计;
  }

  // ═══════════ 导出 ═══════════

  return {
    版本: '0.1.0-核心',
    下一随机, 掷百分, 掷骰,
    判定,
    推进半天, 日计数到阶段,
    STAT_DEF, resolveStat,
    注册事件, 调度tick,
    财富合计,
  };
})();

// 暴露给面板与其他脚本
globalThis.环引擎 = 环引擎;
